NAME=exiv2
VERSION=0.28.9
LICENSE=GPL-2.0-or-later
URL=https://github.com/Exiv2/exiv2/archive/refs/tags/v$VERSION.tar.gz
FILE=exiv2-$VERSION.tar.gz
SHA256=700b76b97695b2fab4ef8c79619c68ae57d09e0c130724791cafbd39e0eb4aef
DEPENDS="ndk-zlib expat"
build() {
  dta_cmake -DEXIV2_ENABLE_XMP=ON -DEXIV2_ENABLE_PNG=ON -DEXIV2_ENABLE_BMFF=ON \
    -DEXIV2_ENABLE_INIH=OFF -DEXIV2_ENABLE_BROTLI=OFF -DEXIV2_ENABLE_NLS=OFF \
    -DEXIV2_ENABLE_WEBREADY=OFF -DEXIV2_ENABLE_CURL=OFF -DEXIV2_ENABLE_LENSDATA=ON \
    -DEXIV2_BUILD_EXIV2_COMMAND=OFF -DEXIV2_BUILD_SAMPLES=OFF -DEXIV2_BUILD_UNIT_TESTS=OFF \
    -DEXIV2_BUILD_FUZZ_TESTS=OFF -DEXIV2_BUILD_DOC=OFF -DBUILD_TESTING=OFF \
    -DEXIV2_ENABLE_VIDEO=OFF
}
